CREATE TYPE "ServicePriceType" AS ENUM ('FIXED','HOURLY','UNIT','PERCENT');
CREATE TYPE "PointKind" AS ENUM ('PICKUP','DELIVERY');
CREATE TYPE "OutsideRule" AS ENUM ('FULL_OUTSIDE','FARTHEST_FROM_MKAD','MANUAL');
CREATE TYPE "RoundingMode" AS ENUM ('NONE','NEAREST','CEIL');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" TEXT NOT NULL DEFAULT 'ADMIN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "VehicleType" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL UNIQUE,"basePriceKopeks" BIGINT NOT NULL DEFAULT 0,"outsidePriceKopeks" BIGINT NOT NULL DEFAULT 0,"minPriceKopeks" BIGINT NOT NULL DEFAULT 0,"maxPayloadTons" DECIMAL(8,2),"bodyLengthM" DECIMAL(8,2),"bodyWidthM" DECIMAL(8,2),"maxCargoLengthM" DECIMAL(8,2),"overloadKopeks" BIGINT NOT NULL DEFAULT 0,"distanceMultiplier" DECIMAL(6,2) NOT NULL DEFAULT 1,"isActive" BOOLEAN NOT NULL DEFAULT true,"comment" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AdditionalService" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"priceType" "ServicePriceType" NOT NULL DEFAULT 'FIXED',"priceValue" DECIMAL(14,2) NOT NULL,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AppSettings" ("id" TEXT PRIMARY KEY DEFAULT 'global',"companyName" TEXT NOT NULL DEFAULT 'Расчет доставки',"phone" TEXT,"currency" TEXT NOT NULL DEFAULT 'RUB',"roundingMode" "RoundingMode" NOT NULL DEFAULT 'CEIL',"outsideBothRule" "OutsideRule" NOT NULL DEFAULT 'FULL_OUTSIDE',"globalDistanceFactor" DECIMAL(6,2) NOT NULL DEFAULT 1,"mkadGeoJson" JSONB,"mkadSource" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Calculation" ("id" TEXT PRIMARY KEY,"number" TEXT NOT NULL UNIQUE,"vehicleTypeId" TEXT NOT NULL,"cargoWeightTons" DECIMAL(8,2) NOT NULL,"comment" TEXT,"totalDistanceKm" DECIMAL(10,3) NOT NULL,"insideDistanceKm" DECIMAL(10,3) NOT NULL,"outsideDistanceKm" DECIMAL(10,3) NOT NULL,"billableDistanceKm" DECIMAL(10,3) NOT NULL,"basePriceKopeksSnapshot" BIGINT NOT NULL,"outsideRateKopeksSnapshot" BIGINT NOT NULL,"distanceMultiplierSnapshot" DECIMAL(6,2) NOT NULL,"servicesKopeks" BIGINT NOT NULL DEFAULT 0,"adjustmentKopeks" BIGINT NOT NULL DEFAULT 0,"adjustmentReason" TEXT,"totalKopeks" BIGINT NOT NULL,"tariffSnapshot" JSONB NOT NULL,"routeGeoJson" JSONB NOT NULL,"routeStatus" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CalculationPoint" ("id" TEXT PRIMARY KEY,"calculationId" TEXT NOT NULL,"kind" "PointKind" NOT NULL,"sortOrder" INTEGER NOT NULL,"displayAddress" TEXT NOT NULL,"normalizedAddress" TEXT NOT NULL,"latitude" DECIMAL(10,7) NOT NULL,"longitude" DECIMAL(10,7) NOT NULL);
CREATE TABLE "CalculationAdditionalService" ("id" TEXT PRIMARY KEY,"calculationId" TEXT NOT NULL,"additionalServiceId" TEXT NOT NULL,"nameSnapshot" TEXT NOT NULL,"priceTypeSnapshot" "ServicePriceType" NOT NULL,"priceValueSnapshot" DECIMAL(14,2) NOT NULL,"quantity" DECIMAL(10,2) NOT NULL DEFAULT 1,"amountKopeks" BIGINT NOT NULL);
ALTER TABLE "Calculation" ADD CONSTRAINT "Calculation_vehicleTypeId_fkey" FOREIGN KEY ("vehicleTypeId") REFERENCES "VehicleType"("id");
ALTER TABLE "CalculationPoint" ADD CONSTRAINT "CalculationPoint_calculationId_fkey" FOREIGN KEY ("calculationId") REFERENCES "Calculation"("id") ON DELETE CASCADE;
ALTER TABLE "CalculationAdditionalService" ADD CONSTRAINT "CalculationAdditionalService_calculationId_fkey" FOREIGN KEY ("calculationId") REFERENCES "Calculation"("id") ON DELETE CASCADE;
ALTER TABLE "CalculationAdditionalService" ADD CONSTRAINT "CalculationAdditionalService_additionalServiceId_fkey" FOREIGN KEY ("additionalServiceId") REFERENCES "AdditionalService"("id");
